from pathlib import Path
import json,hashlib
from PIL import Image
p=Path('prototypes/view-v01');a=Path('art/view_v01')
counts=json.loads((p/'checks.json').read_text(encoding='utf-8'))['lake_counts']
sections=''
for key,label,note in [('forest','树冠结构','同一森林坐标，冠顶与前后枝叶遮挡；角色、景物根点和相机不变。'),('rocks','岩石体块','同一山地坐标，比较岩石顶面与前侧面；原地表纹理保留。'),('lake','湖泊与水岸','同一湖泊中心：候选重新生成不对称湖湾与岬角；远岸露出向水坡面，近岸薄边遮挡，水平水面保持。两图使用相同角色位置、相机偏移与zoom1，展示完整湖形。'),('spawn','出生点地表','同一出生坐标继承山地地表；移除独立亮绿覆盖和固定样例圈，净空仅作用于障碍。')]:
 sections+=f'<section><h2>{label}</h2><p>{note}</p><div class="pair"><figure><img src="{key}-before.png"><figcaption>正式现状</figcaption></figure><figure><img src="{key}-after.png"><figcaption>候选 · 待确认</figcaption></figure></div><details><summary>原尺寸叠加对照（拖动滑块）</summary><div class="compare"><img src="{key}-before.png"><div class="over"><img src="{key}-after.png"></div></div><input aria-label="{label}对比滑块" type="range" value="50" oninput="this.previousElementSibling.querySelector(\'.over\').style.clipPath=\'inset(0 0 0 \'+this.value+\'%)\'"></details></section>'
for c in counts:
 seed=c['seed'];sections+=f'<section><h2>湖泊分布 · Seed {seed}</h2><p>{c["before"]} → {c["after"]} 个（减少 {100*(1-c["after"]/c["before"]):.1f}%）。宏生态控制点相同，保留湖泊中心及生成包络相同；本轮已授权重塑岸线，轮廓不再沿用原椭圆。此图为生成数据总览，非游戏地面画稿。</p><div class="pair maps"><figure><img src="map-{seed}-before.png"><figcaption>原分布</figcaption></figure><figure><img src="map-{seed}-after.png"><figcaption>数量候选</figcaption></figure></div></section>'
html='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>风栖原野 · 统一视角候选 V0.1</title><style>body{margin:0;background:#edeedf;color:#293b31;font:16px/1.65 "Microsoft YaHei",sans-serif}main{max-width:1440px;margin:auto;padding:28px}h1{font-size:28px}h2{font-size:22px}section{background:#fafbf4;border-radius:14px;padding:20px;margin:24px 0}.pair{display:flex;gap:14px}figure{flex:1;min-width:0;margin:0}img{display:block;width:100%;height:auto;border-radius:6px}figcaption{padding:6px}.maps img{max-width:512px;margin:auto;image-rendering:auto}.compare{position:relative;margin-top:14px}.compare .over{position:absolute;inset:0;clip-path:inset(0 0 0 50%)}input{width:100%}a{color:#355e45}.pill{background:#dce6cf;padding:8px 12px;display:inline-block;border-radius:8px}details{margin-top:10px}@media(max-width:800px){.pair{flex-direction:column}main{padding:14px}}</style><main><h1>风栖原野 · 统一场景视角 V0.2</h1><p class="pill">独立候选 · 等待确认 · 未接入正式游戏</p><p>真实 Godot 4.7.2 场景截图，1280×720、Camera2D zoom 1、原四方向部件角色。近正交3/4斜俯视、左上柔光。并排图可点击原图，展开后可叠加比较。</p><p>可玩预览：双击项目根目录 Start-View-Preview.cmd；1旧版 / 2候选，3出生 / 4湖岸 / 5森林 / 6山地，WASD移动。树石图像通过 local:codex-cli / codex-image_gen 生成，保留提示词与来源；未旋转或非等比变形旧图。</p>'''+sections+'''<section><h2>视角辅助样板</h2><img src="view-reference.svg"><p>完整规则见根目录 ART_STYLE.md、VIEW_REFERENCE.md 与 SCENE_ART_WORKFLOW.md。图中几何仅为制作辅助，不替换游戏资源。</p></section><section><h2>验收边界</h2><p>湖岸修订21项专项通过：3 Seed的数量筛选、中心/包络、宏生态权重保持及不规则岸线复现。出生与移动沿用上一轮专项结果，本轮未改动这些规则。实际角色在候选出生点20物理帧移动约63.35单位；沿用原树石碰撞安装与交互代码。</p><p>图集未遵循等格，按手工所有权矩形裁片；原图含低透明彩色雾边，alpha&lt;210清理后等比整理。宽树可见轮廓比原图略矮，细树冠层差异较明显，仍需视觉确认。湖岸是静态材质表达，无真实地形高度或动态水系统。没有全量回归或新性能保证。</p></section></main><script>document.querySelectorAll('figure img').forEach(i=>{i.style.cursor='zoom-in';i.onclick=()=>window.open(i.src,'_blank')})</script></html>'''
(p/'index.html').write_text(html,encoding='utf-8')
baseline=json.loads((a/'baseline.json').read_text());changed=[f for f,h in baseline.items() if hashlib.sha256(Path(f).read_bytes()).hexdigest()!=h]
sizes={n:Image.open(p/(n+'.png')).size==Image.open('assets/environment/stylized_v3/'+n+'.png').size for n in ['tree_0','tree_1','rock_0','rock_1']}
report={'formal_files_changed':changed,'same_logical_canvas':sizes,'candidate_version':'windrest-view-0.2.0','formal_generator':'windrest-biome-0.3.0','source_route':'local:codex-cli','status':'pending_user','collision_note':'candidate stream inherits original install_chunk; no collision/interaction overrides','camera_note':'actual screenshots same world points and zoom; lake screenshots see lake-runtime.json; other views see runtime.json'}
(a/'review.json').write_text(json.dumps(report,indent=2),encoding='utf-8')
print(json.dumps(report))
